"""Config handler"""
from __future__ import print_function
from builtins import str, object
import os
import sys
import json
import re
import copy
from os.path import join, expanduser
from shutil import copyfile
from collections import OrderedDict
from robot.libraries.BuiltIn import BuiltIn
from taf.sbts.oam.coam.admin import admin as ute_admin
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger


ROBOT_LIBRARY_SCOPE = 'GLOBAL'
logger = BackgroundLogger.Instance()


class ConfigHandler(object):
    """Config handler"""
    config = OrderedDict()

    def __init__(self):
        pass

    def get_variables(self):
        """Get variables"""
        if not "--dryrun" in sys.argv and not self.config:
            self._create_softlink()
            bts_id = ConfigHandler.config['bts_id'] = BuiltIn().get_variable_value("${bts_id}", '1')
            if '__init__.py' in bts_id:
                bts_id = self.read_bts_id_from_file(bts_id)
            ConfigHandler.config['fw_user_path'] = self.get_path()
            ConfigHandler.config['config_base_path'] = join(ConfigHandler.config['fw_user_path'], 'config', bts_id)
            robot_script_path = os.path.dirname(BuiltIn().get_variable_value("${SUITE SOURCE}"))
            ConfigHandler.config['common_resources_path'] = join(robot_script_path, os.pardir, 'resources')
            # logger.info('common_resources_path: {}'.format(ConfigHandler.config['common_resources_path']))

            ConfigHandler.config['feature_resources_path'] = join(robot_script_path, 'resources')

            self.get_consolidated_config(ConfigHandler.config)
            # ConfigHandler.config['rat_env'] = ['lte', 'wcdma', 'gsm'] if ConfigHandler.config['rat_env'].lower() ==\
            #                                                              'sran' else ['lte']
            self._interpret_rat_env()
            self.get_variables_from_ute_config()
            # ConfigHandler.config["wft_filters_file"] = join(ConfigHandler.config['common_resources_path'],
            #                                                 'wft_filters.json')
            self.config['scfc_path'] = join(ConfigHandler.config['config_base_path'], 'scfc_files')
            ConfigHandler.config["delta_files"] = join(ConfigHandler.config['config_base_path'], 'delta_files')
            ConfigHandler.config['chained_bts_scf_dir'] = join(ConfigHandler.config['fw_user_path'], 'config',
                                                               '{chained}', 'scfc_files')
            # ConfigHandler.config["rise_csv"] = join(ConfigHandler.config['common_resources_path'],
            #                                         ConfigHandler.config['rise_csv'])
            self.config = dict((k.lower(), v) for k, v in self.config.items())  # convert dict keys to lower case
        return self.config

    def _create_softlink(self):
        host_home_path = expanduser("~")
        prefix_path = self._get_working_prefix_path(host_home_path)
        if prefix_path:
            fw_user_path_full = '{}{}'.format(prefix_path, 'fw_user_path/')
            fw_user_path_symlink = self._make_symlinks(fw_user_path_full, host_home_path)
            # Framework path setting is not required for package approach
            sys.path.insert(0, fw_user_path_symlink)
            return {}
        else:
            raise Exception('FW Path Softlinks creation failed')

    def _get_working_prefix_path(self, host_home_path):
        robot5gws_home = '/Auto5G/'
        robotws5g_home = '/robotws/'
        robotws_home = '/MN/UTE/robotws/'
        robotlte_home = '/MN/UTE/robotlte/'
        robotlte_temp_home = '/robotlte/'  # This temp path will be replaced with the use of robotlte_home
        docker_mode_home = '/test_repository/'
        robot5gws_middle_path = 'testsuite/TRS/Bangalore/E2E_BTS_TRS_FW/'
        robotws5g_middle_path = 'testsuite/Bangalore/TRS/E2E_BTS_TRS_FW/'
        robotlte_middle_path = 'testsuite/WMP/E2E_BTS_TRS_FW/'

        # delete this part after MN path issue is fixed. robotws should always be preferred over robotlte. robotlte
        # is expected to be merged with robotlte by 24r2.
        # actual code:
        # home_paths = [robotws_home, robotws5g_home, robot5gws_home, robotlte_home, robotlte_temp_home,
        # docker_mode_home]
        if "robotws" in os.getcwd():
            home_paths = [robotws_home, robotws5g_home, robot5gws_home, robotlte_home, robotlte_temp_home,
                          docker_mode_home]
        elif "robotlte" in os.getcwd():
            home_paths = [robotlte_home, robotlte_temp_home, robotws_home, robotws5g_home, robot5gws_home,
                          docker_mode_home]

        middle_paths = [robotws5g_middle_path, robot5gws_middle_path, robotlte_middle_path]

        # home_paths = [robotws_home, robotlte_home]
        for home_path in home_paths:
            for middle_path in middle_paths:
                prefix_path = '{}{}{}'.format(host_home_path, home_path, middle_path)
                if os.path.exists(prefix_path):
                    return prefix_path
        return None

    def _make_symlinks(self, fw_user_path_full, home_dir):
        fw_user_path_symlink = '{}/fw_user_path'.format(home_dir)
        if os.path.islink(fw_user_path_symlink):
            pass
        else:
            os.symlink(fw_user_path_full, fw_user_path_symlink)
        return fw_user_path_symlink

    def _interpret_rat_env(self):
        rat_list = ConfigHandler.config['rat_env']
        interpreted_rat_set = []
        if not isinstance(rat_list, list):
            rat_list = [rat_list]
        valid_status = ['commissioned', 'onairdone', 'configured', 'prevalidated', 'validated', 'initializing']
        try:
            alias1 = self._setup_oam_ops()
            try:
                cell_status_dict = self._get_cell_status_dict(100, alias1)
            except Exception as e:
                raise e
            finally:
                self.admin.teardown_admin(connection=alias1)
            interpreted_rat_set = {k for k, v in cell_status_dict.items() if v.lower() in valid_status}
        except Exception as rat_e:
            logger.info("Finding interpreted rat env is applicable for classical bts only. Falling back to default "
                        "rat_env value in testline_config.")

        if not interpreted_rat_set:
            logger.info("Could not find any RATs in valid state on bts. Falling back to default rat_env value in "
                        "testline_config.")
            interpreted_rat_set = {item for item in rat_list}

        ConfigHandler.config['rat_env_without_common'] = copy.deepcopy(list(interpreted_rat_set))
        interpreted_rat_set.add('common')
        ConfigHandler.config['rat_env'] = list(interpreted_rat_set)
        print("rat_env update: ", interpreted_rat_set, ConfigHandler.config['rat_env'])

    def _setup_oam_ops(self):
        logger.debug("setting up oamops....")
        self.admin = ute_admin()
        alias1 = 'internal_call'
        self.admin.setup_admin(bts_host="192.168.255.129", bts_port=443, username="Nemuadmin", password="nemuuser", use_ssl=True, name=alias1)
        return alias1

    def get_variables_from_ute_config(self):
        """Get variables from ute config"""
        tl = BuiltIn().get_variable_value('${tl}')
        if tl is not None:
            try:
                tl = dict(tl[1])
            except Exception:
                tl = {}
            if tl.get('vlan_ids'):
                self.config['vlan_ids'] = re.findall(r'\d+', tl.get('vlan_ids'))
                logger.debug('vlan_ids', self.config['vlan_ids'])

    def get_consolidated_config(self, config):
        """Get consolidated config"""
        # combine testline,common,feature specific config
        cmd_line_args_dict = self._get_command_line_arg_as_dict(sys.argv)
        ConfigHandler.config.update(cmd_line_args_dict)
        testcase_variables_file = cmd_line_args_dict.get('tc_variables', 'testcase_variables.json')
        config_files = [join(ConfigHandler.config['config_base_path'], 'testline_config.json'),
                        join(ConfigHandler.config['common_resources_path'], testcase_variables_file),
                        join(ConfigHandler.config['feature_resources_path'], testcase_variables_file)]
        logger.info('Config Files: <{}> '.format(config_files))
        for config_file in config_files:
            if os.path.exists(config_file):
                self.add_json_to_config(config_file, config)
                config_path = os.path.dirname(config_file)
                config_file_dest_name = os.path.basename(config_path) + '_' + os.path.basename(config_file)
                self.copy_config_file(config_file, config_file_dest_name)
            else:
                logger.warn('File <{}> does not exist'.format(config_file))

    def copy_config_file(self, src, dest_filename):
        """Copy config file"""
        dest = 'execution_logs/{}'.format(dest_filename)
        logger.debug("Configuration file copied to: {}".format(dest))
        if not os.path.exists(os.path.dirname(dest)):
            os.makedirs(os.path.dirname(dest))
        copyfile(src, dest)
        return dest

    def add_json_to_config(self, config_file, config):
        """Add json to config"""
        print('Consolidating config {} '.format(config_file))
        with open(config_file, "r") as file_handle:
            json_data = json.load(file_handle, object_pairs_hook=OrderedDict)
            config.update(json_data)

    def get_path(self):
        """Get path"""
        home_dir = expanduser("~")
        return '{}/fw_user_path'.format(home_dir)

    def read_bts_id_from_file(self, file_path):
        with open(file_path) as f:
            lines = f.readlines()
        for line in lines:
            if re.match('bts_id', line):
                print("#### found {}".format(line))
                bts_id = line.split("=")
                return bts_id[1].strip()
        else:
            raise Exception("bts_id is not found in the given variable file")

    @classmethod
    def get_config(cls):
        """Get config"""
        if not cls.config:
            cls.config = cls().get_variables()
        return cls.config

    def _get_command_line_arg_as_dict(self, argv):
        try:
            return dict(item.split(":", 1) for item in ([argv[i + 1] for i, value in enumerate(argv) if value == '-v']))
        except Exception as e:
            return {}

    def replace_moc(self, adict, k):
        """Replace moc"""
        for key in list(adict.keys()):
            if key == k:
                value = adict[key]
                new_value = value.replace("{bts_id}", BuiltIn().get_variable_value("${bts_id}"))
                adict[key] = new_value
            elif type(adict[key]) is dict:
                self.replace_moc(adict[key], k)

    COMMON = {
    }

    def _get_cell_status_dict(self, timeout, alias1):
        cell_status_dict = {}
        try:
            all_cells_data = self.admin.get_managed_objects(class_name='CELL_M', timeout=float(timeout),
                                                            connection=alias1)
            for cell_data in all_cells_data:
                cell_rat = cell_data['parameters']['rat'].lower()
                cell_status = cell_data['parameters']['stateInfo']['proceduralState']
                # if cell_rat == "nr":
                #     cell_rat = "5g" # relacing nr with 5g throws validation error
                cell_status_dict[cell_rat] = cell_status.lower()
            logger.debug(cell_status_dict)
        except Exception as err:
            raise err
        return cell_status_dict


def get_variables():
    """Get variables"""
    return ConfigHandler().get_variables()
